--
-- Table structure for table `room_history`
--

DROP TABLE IF EXISTS `room_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `room_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '房间记录自增ID',
  `room_code` char(6) NOT NULL COMMENT '6位房间码',
  `host_user_id` bigint NOT NULL COMMENT '房主用户ID',
  `config_json` json NOT NULL COMMENT '房间配置快照（RoomConfig JSON）',
  `started_at` datetime NOT NULL COMMENT '房间创建时间',
  `ended_at` datetime DEFAULT NULL COMMENT '房间关闭时间；NULL 表示仍在进行',
  PRIMARY KEY (`id`),
  KEY `idx_room_code` (`room_code`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='房间生命周期历史表';
/*!40101 SET character_set_client = @saved_cs_client */;

