DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户自增ID',
  `username` varchar(32) NOT NULL COMMENT '登录用户名',
  `password_hash` varchar(60) NOT NULL COMMENT 'bcrypt 密码哈希',
  `display_name` varchar(32) NOT NULL COMMENT '显示昵称',
  `chip_balance` bigint NOT NULL DEFAULT '10000' COMMENT '账户筹码余额',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户账户表';
